        peerCall_.answer(stream);
        peerCall_.on('close',function(){
            var $remoteAudio_ = $('#remote');
            $remoteAudio_[0].pause();
            enableForm_('connect');
            if($('.session:last .message').length > 0){
                var isAtBottom = ui.checkIsAtBottom();
                $('.session:last').append(
                    '<div class="datetime">' +
                        '<time>'+new Date().toLocaleString()+'</time>' +
                        '</div>');
                if(isAtBottom){
                    ui.scrollToBottom();
                }
